def transform(grid):
    split = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    colors = sorted({v for row in grid for v in row if v not in (0, 5)})
    top = {c: sum(v == c for row in grid[:split] for v in row) for c in colors}
    bottom = {c: sum(v == c for row in grid[split + 1:] for v in row) for c in colors}
    chosen = max(colors, key=lambda c: (bottom[c] - top[c], top[c] + bottom[c]))
    return [[chosen, chosen], [chosen, chosen]]

def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(out), len(out[0])
    gaps = []
    # Complete one-cell breaks within horizontal runs.
    for r in range(height):
        for c in range(1, width - 1):
            color = out[r][c - 1]
            if color != 0 and out[r][c] == 0 and out[r][c + 1] == color:
                out[r][c] = color
                gaps.append((r, c, color))
    # Each completed break extends upward, stopping at the next colored cell.
    for r, c, color in gaps:
        rr = r - 1
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1
    return out

def transform(grid):
