from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    groups = []
    for r, row in enumerate(out):
        if len(set(row)) > 1:
            if groups and r == groups[-1][-1] + 1:
                groups[-1].append(r)
            else:
                groups.append([r])
    counts = Counter(v for row in out for v in row)
    best = None
    for i, ga in enumerate(groups):
        if len(ga) < 2:
            continue
        for gb in groups[i + 1:]:
            if len(gb) != len(ga):
                continue
            for color in counts:
                if color == 1:
                    continue
                for shift in range(-w + 1, w):
                    a, b, clipped = set(), set(), 0
                    for k, (ra, rb) in enumerate(zip(ga, gb)):
                        for j, value in enumerate(out[ra]):
                            if value == color:
                                jj = j + shift
                                if 0 <= jj < w:
                                    a.add((k, jj))
                                else:
                                    clipped += 1
                        for j, value in enumerate(out[rb]):
                            if value == color:
                                b.add((k, j))
                    mismatch = len(a ^ b)
                    score = mismatch + 2 * clipped
                    key = (score, counts[color], mismatch, clipped)
                    if best is None or key < best[0]:
                        best = (key, ga, gb, color, shift, len(a), len(b))
    if best is not None:
        _, ga, gb, color, shift, na, nb = best
        if na >= nb:
            source, target, source_is_a = ga, gb, True
        else:
            source, target, source_is_a = gb, ga, False
        for sr, tr in zip(source, target):
            if source_is_a:
                for j, value in enumerate(out[sr]):
                    jj = j + shift
                    if value == color and 0 <= jj < w and out[tr][jj] != color:
                        out[tr][jj] = 1
            else:
                for j, value in enumerate(out[sr]):
                    jj = j - shift
                    if value == color and 0 <= jj < w and out[tr][jj] != color:
                        out[tr][jj] = 1
        return out
    color = min((c for c in counts if c != 1), key=lambda c: counts[c])
    for row in out:
        if color in row and len(set(row)) > 1:
            for j, value in enumerate(row):
                if value != color:
                    row[j] = 1
    return out

