    if len(counts) >= 2:
        foreground = min(counts, key=counts.get)
        background = max(counts, key=counts.get)
        periodic_group = None
        for group in groups:
            candidates = []
            for r in group:
                row = out[r]
                j = w - 1
                while j >= 0 and row[j] == background:
                    j -= 1
                tail_start = j + 1
                if w - tail_start < 3:
                    candidates.append((r, None, tail_start))
                    continue
