                k = tail_start - 1
                run_len = 0
                while k > 0 and row[k] != row[k - 1] and {row[k], row[k - 1]} == {foreground, background}:
                    run_len += 1
                    k -= 1
                if run_len:
                    run_len += 1
                candidates.append((r, run_len if run_len >= 2 else None, tail_start))
