            for r, run_len, start in periodic_group:
                row = out[r]
                if run_len is None:
                    if start > 0 and row[start - 1] == foreground and row[start] == background:
                        fill_from = start + 1
                        expected = foreground
                    else:
                        continue
                else:
                    fill_from = start
                    expected = foreground if row[start - 1] == background else background
                for c in range(fill_from, w):
