    threshold = max(12, int(w * 0.60))
    for bi, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[bi + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            for off in range(a1 - a0):
                ra, rb = a0 + off, b0 + off
                rowa, rowb = grid[ra], grid[rb]
                prefix = 0
                while prefix < w and rowa[prefix] == rowb[prefix]:
                    prefix += 1
                if prefix >= threshold:
                    ca = sum(v == foreground for v in rowa)
                    cb = sum(v == foreground for v in rowb)
                    src, dst = (rowa, rb) if ca > cb else (rowb, ra) if cb > ca else (None, None)
                    if src is not None:
                        for c in range(prefix, w):
                            if src[c] == foreground and out[dst][c] == background:
                                out[dst][c] = 1

