                            end += 1
                        return first, end - first
                    sa, la = lead(rowa)
                    sb, lb = lead(rowb)
                    if sa is None or sa != sb or la == lb:
                        continue
                    src, dst, delta = (rowa, rb, lb - la) if la < lb else (rowb, ra, la - lb)
                    if delta <= 0 or delta > 3:
