def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    up = down = 0
    while cells:
        start = cells.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells:
                    cells.remove(q)
                    comp.add(q)
                    stack.append(q)
        if len(comp) != 4:
            continue
        rmin = min(r for r, c in comp)
        rmax = max(r for r, c in comp)
        cmin = min(c for r, c in comp)
        cmax = max(c for r, c in comp)
        normalized = {(r-rmin, c-cmin) for r, c in comp}
        if normalized == {(0,1),(1,0),(1,1),(1,2)}:
            up += 1
        elif normalized == {(0,0),(0,1),(0,2),(1,1)}:
            down += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0,0),(2,0),(0,2),(2,2))
    for n, color, offset in ((up,3,0),(down,1,3)):
        for r, c in slots[:min(n,4)]:
            out[r][offset+c] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            boxes = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    b = boxes[color]
                    b[0] = min(b[0], y); b[1] = max(b[1], y)
                    b[2] = min(b[2], x); b[3] = max(b[3], x)
            colors = sorted(boxes, key=lambda color: -((boxes[color][1]-boxes[color][0]+1)*(boxes[color][3]-boxes[color][2]+1)))
            mapping = dict(zip(colors, reversed(colors)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            boxes.append((min(rs), max(rs), min(cs), max(cs)))

    targets = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1 in boxes):
                targets.append((r,c))

    out = [row[:] for row in grid]
    for r, c in targets:
        for y in range(max(0,r-1), min(h,r+2)):
            for x in range(max(0,c-1), min(w,c+2)):
                if out[y][x] != 2:
                    out[y][x] = 1
    return out

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    row_cuts = [r for r, row in enumerate(g) if row[0] != 0 and all(v == row[0] for v in row)]
    col_cuts = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]
    def bands(size, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < size:
            out.append((start, size))
        return out
    rows = bands(h, row_cuts)
    cols = bands(w, col_cuts)
    for r0, r1 in rows:
        for j in range(0, len(cols) - 1, 2):
            c0, c1 = cols[j]
            d0, d1 = cols[j + 1]
            if c1 - c0 != d1 - d0 or r1 - r0 != rows[rows.index((r0, r1))][1] - rows[rows.index((r0, r1))][0]:
                continue
            left = any(g[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1))
            right = any(g[r][c] != 0 for r in range(r0, r1) for c in range(d0, d1))
            if left == right:
                continue
            src0, dst0 = (c0, d0) if left else (d0, c0)
            for r in range(r0, r1):
                for x in range(c1 - c0):
                    g[r][dst0 + x] = g[r][src0 + (c1 - c0 - 1 - x)]
    return g

