    tiles = []
    for r in range(height - 1):
        for c in range(width - 1):
            window = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            cells = window & occupied
            if len(cells) == 4:
                tiles.append((cells, 1, None))
            for triple in combinations(sorted(cells), 3):
                missing = next(iter(window - set(triple)))
                color = {(r, c): 2, (r + 1, c): 3, (r, c + 1): 4, (r + 1, c + 1): 5}[missing]
                tiles.append((set(triple), color, missing))

    solutions = []
