from collections import deque


def transform(grid):
    height, width = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                x, y = queue.popleft()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < height and 0 <= ny < width
                            and grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        cells.add((nx, ny))
                        queue.append((nx, ny))
            objects.append((color, cells))

    positions = [cells for _, cells in objects]
    while True:
        moving = [all(c + 1 < width for _, c in cells) for cells in positions]
        changed = True
        while changed:
            changed = False
            for i, cells in enumerate(positions):
                if not moving[i]:
                    continue
                destination = {(r, c + 1) for r, c in cells}
                for j, other in enumerate(positions):
                    if i != j and not moving[j] and destination & other:
                        moving[i] = False
                        changed = True
                        break
        if not any(moving):
            break
        positions = [({(r, c + 1) for r, c in cells} if moving[i] else cells)
                     for i, cells in enumerate(positions)]

    output = [[0] * width for _ in range(height)]
    for (color, _), cells in zip(objects, positions):
        for r, c in cells:
            output[r][c] = color
    return output

