def transform(grid):
    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    directions = ((-1, 0), (1, 0), (0, -1), (0, 1))
    seen = set()
    labels = {}
    components = []
    object_colors = {background}

    for row in range(height):
        for col in range(width):
            color = grid[row][col]
            if color == background or (row, col) in seen:
                continue
            stack = [(row, col)]
            seen.add((row, col))
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < height and 0 <= nc < width and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if len(cells) >= 4:
                object_colors.add(color)
                component_id = len(components)
                components.append(color)
                for cell in cells:
                    labels[cell] = component_id

    output = [row[:] for row in grid]
    for row in range(height):
        for col in range(width):
            if grid[row][col] in object_colors:
                continue
            neighbors = {}
            for dr, dc in directions:
                nr, nc = row + dr, col + dc
                component_id = labels.get((nr, nc))
                if component_id is not None:
                    color = components[component_id]
                    neighbors.setdefault(color, set()).add(component_id)
            fills = [color for color, ids in neighbors.items()
                     if len(ids) == 1 and sum(
                         1 for dr, dc in directions
                         if 0 <= row + dr < height and 0 <= col + dc < width
                         and grid[row + dr][col + dc] == color) >= 2]
            output[row][col] = fills[0] if len(fills) == 1 else background

    return output

