def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The intact section reveals the diagonal color cycle. The top-left
    # three-cell frame is separate from the repeating field.
    samples = [(r, c, grid[r][c])
               for r in range(3, h) for c in range(6, w)
               if grid[r][c] != 0]
    period = len({v for _, _, v in samples})
    votes = defaultdict(Counter)
    for r, c, value in samples:
        votes[(r + c) % period][value] += 1
    phase = {p: counts.most_common(1)[0][0] for p, counts in votes.items()}

